import fs from 'node:fs/promises'
import {dir,db,asset,send,reviewed,task} from './reply-runtime-20261007.mjs'
const s=JSON.parse(await fs.readFile(dir+'/reply-refresh.json','utf8'));const plans=[]
const get=n=>{const t=s.threads.find(t=>t.contact.name===n);if(!t)throw Error('Missing '+n);return t}
async function add(name,body,card=false){const t=get(name),c=t.contact;plans.push({id:c.id,name,phone:c.phone,city:c.city,latest:t.touches.at(-1).id,from:'+14374650584',body,...(card?{media_urls:[await asset(c.city)]}:{})})}
for(const name of ['SEHAR MALIK','Steve Manning','Selma Brisebois','COLLEEN S. BROWN','TANIA SPRING','Maurice Haineault','BERBO BUSTAMANTE','Madie Walker','Kevin Broome','MATHEW JACOB','MONICA TRAN','CHRIS BAXTER','SHARON ALEX','Dexter Sargeant','CHRIS ROSELLI','TONY CICCONE']){const c=get(name).contact,first=name.split(' ')[0].toLowerCase().replace(/^./,x=>x.toUpperCase());await add(name,`Here you go, ${first}! Here's our ${c.city} card. Feel free to save it and share it when a client needs moving help.`,true)}
await add('VIR DAVE',"Yes, Vir, we cover Orangeville and Vaughan. Here's our card to keep handy. If you have a move in mind, send the date, pickup and delivery locations, and the items to be moved so we can check availability and work out a quote.",true)
await add('JASON JOE LUPO',"Here's our Markham card, Jason. We can help with furniture moves for home staging. Do you have a particular pickup in mind, or are you looking for an ongoing moving option? Also, is there a language preference for your client that you'd like us to check?",true)
await add('VIDUR ARORA',"Thanks Vidur, I appreciate it. No problem if Fawad has already found someone. Feel free to send the next lead my way and we'll take it from there.")
await add('MICHAEL KA LIT HO',"Hi Michael, I'm reaching out about moving services for your clients rather than a property search. I'm John from Saturn Star Movers. Would you like our digital card to keep handy when a buyer or seller needs a mover?")
await fs.writeFile(dir+'/1615-reply-plan.json',JSON.stringify(plans,null,2));for(const p of plans)await send(p)
await task(get('JASON JOE LUPO').contact,'20261007-jason-staging','Jason Lupo: staging furniture enquiry','Requested card for staging furniture pickup; Markham card sent. Asked particular pickup versus ongoing need, and whether a client has language preference. Asked whether John is Chinese; no ethnicity or language capability invented. Await scope/route/date and respond from actual owner facts.')
await db('crm_tasks',{id:'eq.evening-20261006-20261007-sim-condo'},'PATCH',{title:'Sim Uppal: call received; review outcome before next follow-up',description:'After scope/flat-price reply Sim called October 7 at 15:08 Toronto; recorded 135 seconds (REfc77f8a2fe4ab65ab66491a7a4814e4b, CA8a30cd3e03c449518e9d0ebbe0634134). Owner call supersedes awaiting call permission. Review recording/owner outcome before another message or quote; no price or booking inferred from call metadata.'})
for(const t of s.threads){if(plans.some(p=>p.id===t.contact.id)||t.contact.name==='SIM UPPAL')continue;for(const touch of t.touches.filter(x=>x.direction==='inbound'&&!x.metadata?.partnership_review))await reviewed(touch.id,t.contact.name==='Happy Wednesday'?'Repeated leasing assistant response; not partnership interest. Route paused for management identity review.':'Acknowledgement/reaction or saved-contact response reviewed; no extra outbound needed.');await db('market_contacts',{id:'eq.'+t.contact.id},'PATCH',{sequence_paused:true,sequence_paused_reason:t.contact.name==='Happy Wednesday'?'leasing_assistant_not_partnership_contact':'human_managed_relationship',next_follow_up:null})}
await task(get('Happy Wednesday').contact,'20261007-greenwin-route','Review 7-11 Manhattan Court management route','Repeated Vivian leasing-assistant messages, no partnership authority. Preserve original identity evidence; do not converse with leasing bot or treat replies as partnership interest. Verify management contact before future outreach.')
console.log('Completed 18 cards and 2 text replies; acknowledgements reviewed.')
